export const FIXTURE_BIN = join(
	dirname(fileURLToPath(import.meta.url)),
	"fixtures",
	"native-bin",
);
export const fixtureEnv = (extra: Record<string, string> = {}) => ({
	...process.env,
	PATH: `${FIXTURE_BIN}:${process.env.PATH}`,
	...extra,
});
export const UUID = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/;
/** Linux-only assertions skip gracefully elsewhere; ownership fails closed there. */
export const linux = process.platform === "linux";

let root: string | undefined;
export function scratch(name: string): string {
	if (!root) {
		root = mkdtempSync(join(tmpdir(), "native-harness-test-"));
		const owned = root;
		process.once("exit", () => rmSync(owned, { recursive: true, force: true }));
	}
	return mkdtempSync(join(root, `${name}-`));
}

export function role(
	overrides: Partial<NativeRoleDefinition> = {},
): NativeRoleDefinition {
	return {
		name: "native-worker",
		cli: "claude",
		tools: "read, bash",
		autoExit: true,
		body: "You are a native worker.",
		...overrides,
	};
}

export function runHook(hook: string, config: string, payload: JsonObject) {
	return spawnSync("python3", [hook, config], {
		input: JSON.stringify(payload),
		encoding: "utf8",
	});
}

export function processRunIn(dir: string, id = "run-1"): ProcessRun {
	mkdirSync(dir, { recursive: true });
	return createProcessRun(id, join(dir, "process.json"));
}

export function killGroup(pid: number | undefined) {
	try {
		if (pid) process.kill(-pid, "SIGKILL");
	} catch {
		// Already gone.
	}
}

export async function waitFor(check: () => boolean, timeoutMs = 5000) {
	const deadline = Date.now() + timeoutMs;
	while (!check()) {
		if (Date.now() > deadline) throw new Error("timed out waiting");
		await new Promise((resolve) => setTimeout(resolve, 20));
	}
}

export interface Harness {
	operations: PiLaunchOperations;
	children: ChildProcess[];
	events: string[];
	closed: string[];
	send(surface: string, text: string): void;
	/** Model the interrupt key reaching the native TUI. */
	interrupt(surface: string): void;
	/** Model a human typing a prompt into the native TUI. */
	human(surface: string, text: string): void;
}

export function fakeHerdr(options: {
	mode?: string;
	log: string;
	env?: Record<string, string>;
	createWorktree?: PiLaunchOperations["createWorktree"];
	/**
	 * Dispatch the script, then report a delivery failure: on every run, or
	 * only on the given 1-based run call.
	 */
	failAfterRun?: boolean | number;
	/** Return only once the wrapper recorded its exit (fast-exit races). */
	waitForExit?: boolean;
	/** Refuse to dispatch: the script is never staged or started. */
	failBeforeRun?: boolean;
	/** Runs as a dispatch begins (after the launch's pre-dispatch steps). */
	onRun?: (surface: string) => void;
	/** Replace the shell-readiness wait (called with a 1-based call count). */
	waitForShellReady?: (surface: string, call: number) => Promise<void>;
}): Harness {
	const children: ChildProcess[] = [];
	const events: string[] = [];
	const closed: string[] = [];
	const bySurface = new Map<string, ChildProcess>();
	let panes = 0;
	const write = (surface: string, line: string) =>
		bySurface.get(surface)?.stdin?.write(`${line}\n`);
	const operations: PiLaunchOperations = {
		createPane(name) {
			events.push(`create:${name}`);
			return `pane-${++panes}`;
		},
		createWorktree:
			options.createWorktree ??
			(() => {
				throw new Error("unexpected worktree creation");
			}),
		async waitForShellReady(surface) {
			events.push("ready");
			const call = events.filter((event) => event === "ready").length;
			await options.waitForShellReady?.(surface, call);
		},
		runScript(surface, command, script) {
			options.onRun?.(surface);
			if (options.failBeforeRun)
				throw new Error("herdr refused to run the script in the pane");
			events.push("run");
			// The real staging used by runScriptInPane, without Herdr delivery.
			stageScript(command, script);
			const child = spawn("bash", [script.scriptPath], {
				detached: true,
				stdio: ["pipe", "ignore", "ignore"],
				env: fixtureEnv({
					FAKE_NATIVE_MODE: options.mode ?? "ok",
					FAKE_NATIVE_LOG: options.log,
					...options.env,
				}),
			});
			children.push(child);
			bySurface.set(surface, child);
			if (options.waitForExit) {
				const receipt = command.match(
					/mv -f -- '[^']+' '([^']+process\.json)'/,
				)?.[1];
				const sleeper = new Int32Array(new SharedArrayBuffer(4));
				const deadline = Date.now() + 10_000;
				const exited = () => {
					try {
						return /"exitCode"/.test(readFileSync(receipt ?? "", "utf8"));
					} catch {
						return false;
					}
				};
				while (receipt && !exited() && Date.now() < deadline)
					Atomics.wait(sleeper, 0, 0, 20);
			}
			const runCall = events.filter((event) => event === "run").length;
			if (options.failAfterRun === true || options.failAfterRun === runCall) {
				// Fail only once the wrapper has provably started (its receipt
				// exists), modelling a lost acknowledgement after dispatch.
				const receipt = command.match(
					/mv -f -- '[^']+' '([^']+process\.json)'/,
				)?.[1];
				const sleeper = new Int32Array(new SharedArrayBuffer(4));
				const deadline = Date.now() + 5_000;
				while (receipt && !existsSync(receipt) && Date.now() < deadline)
					Atomics.wait(sleeper, 0, 0, 20);
				throw new Error("herdr pane run acknowledgement was lost");
			}
			return script.scriptPath;
		},
		closePane(surface) {
			closed.push(surface);
		},
	};
	return {
		operations,
		children,
		events,
		closed,
		send: write,
		interrupt: (surface) => write(surface, "ESC"),
		human: (surface, text) => write(surface, `HUMAN ${text}`),
	};
}

