export interface ParentSessionPaths {
	sessionDir: string;
	sessionFile: string;
}

export function parentSession(project: string): ParentSessionPaths {
	const sessionDir = join(
		project,
		"..",
		`${project.split("/").pop()}-sessions`,
	);
	mkdirSync(sessionDir, { recursive: true });
	return { sessionDir, sessionFile: join(sessionDir, "parent.jsonl") };
}

export function nativeRequest(
	project: string,
	harness: "claude" | "kiro",
	overrides: Partial<FreshNativeLaunchRequest> = {},
	roleOverrides: Partial<NativeRoleDefinition> = {},
): FreshNativeLaunchRequest {
	const { sessionDir, sessionFile } = parentSession(project);
	const task = overrides.task ?? "Implement the bounded change.";
	const spec = resolveNativeLaunchSpec(
		role({
			cli: harness,
			tools: harness === "claude" ? "read,bash" : "read",
			thinking: "high",
			model: "fixture-model",
			...roleOverrides,
		}),
	);
	return {
		kind: "native",
		id: `native-${harness}`,
		name: "Native worker",
		task,
		agent: `${harness}-worker`,
		parent: {
			cwd: project,
			sessionFile,
			sessionId: "parent",
			sessionDir,
			agentDir: join(project, "..", "agent"),
		},
		behavior: { interactive: spec.mode === "interactive" },
		plan: planNativeLaunch(spec, {
			task,
			parentSessionFile: sessionFile,
			installedSkills: () => [],
		}),
		...overrides,
	};
}

export function watchDeps(harness: Harness, terminated: string[] = []) {
	return {
		send: harness.send,
		inspectPane: async () => ({
			kind: "present" as const,
			agentStatus: "done" as const,
			observedAt: Date.now(),
		}),
		readVisiblePane: async () => "",
		terminate: (processRun: ProcessRun) => {
			terminated.push(processRun.id);
			return terminateProcessRun(processRun);
		},
		intervalMs: 20,
		terminationGraceMs: 3000,
	};
}

export function initRepo(project: string): string {
	execFileSync("git", ["init", "-q", "-b", "main"], { cwd: project });
	for (const [key, value] of [
		["user.email", "test@example.com"],
		["user.name", "Test"],
		["commit.gpgsign", "false"],
	])
		execFileSync("git", ["config", key, value], { cwd: project });
	writeFileSync(join(project, "base.txt"), "base\n");
	execFileSync("git", ["add", "."], { cwd: project });
	execFileSync("git", ["commit", "-qm", "base"], { cwd: project });
	return execFileSync("git", ["rev-parse", "HEAD"], {
		cwd: project,
		encoding: "utf8",
	}).trim();
}

export function assertMatchesAll(text: string, patterns: RegExp[]): void {
	for (const pattern of patterns) assert.match(text, pattern);
}
